CODENAME = "flow"
VERSION_META = {"version": "9.5.43", "codename": "flow", "release_notes": [{"version": "9.5.43", "date": "", "title": "Flow app 운영 개선 통합 요약", "tag": "rollup", "changes": ["SplitTable, Tracker, Inform, Dashboard, Admin, Flow-i/LLM 연동, 대용량 DB 대응을 운영 흐름 기준으로 통합 정리.", "사용자 데이터와 DB/runtime root는 setup.py 번들에 포함하지 않고 외부 FLOW_DATA_ROOT/FLOW_DB_ROOT 또는 로컬 ignored root에 보존.", "버전 정보와 배포 메타는 VERSION.json을 기준으로 확인."]}]}


def _version_time_label() -> str:
    times = []
    for fp in (ROOT / 'VERSION.json', ROOT / 'setup.py'):
        try:
            times.append(fp.stat().st_mtime)
        except OSError:
            pass
    if not times:
        return "unknown"
    return datetime.datetime.fromtimestamp(max(times)).isoformat(timespec="seconds")


